// Some portions generated by Claude
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import {computeEdgePorts, optimizeEdgeBends, placeEdgeLabels, edgeGeometry, edgePortKey, graphNodeSize, edgeLabelSize, boxIntersectionArea, segmentDistance, segmentDistanceWithin} from "../../../main/frontend/graph-explorer/graph-geometry.ts";
import {routeReadability} from './fixtures/readability-measurements.mjs';

const cases = JSON.parse(await readFile(new URL("./fixtures/geometry-reference.json", import.meta.url)));
test("routing retains stable ports and improves obstacle validity; labels require clear space", () => {
  for (const {graph, ports, bends} of cases) {
    const actualPorts = computeEdgePorts(graph.nodes, graph.edges);
    assert.deepEqual([...actualPorts], ports);
    const routed = optimizeEdgeBends(graph.nodes, graph.edges, 2);
    assert.deepEqual(routed, optimizeEdgeBends(graph.nodes, graph.edges, 2));
    const positions = new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}]));
    assert.ok(routeReadability(graph, positions, routed).exactRoutedObstructions <=
      routeReadability(graph, positions, new Map(bends)).exactRoutedObstructions);
    const nodes = new Map(graph.nodes.map(n => [n.id, n]));
    const curves = new Map(graph.edges.map(e => [e.id, edgeGeometry(nodes.get(e.source), nodes.get(e.target), 0,
      actualPorts.get(edgePortKey(e.id, e.source)), actualPorts.get(edgePortKey(e.id, e.target)))]));
    // The old snapshot includes overlapping labels and blocked routes. Keep
    // its stable ports, but assert readability rather than freezing defects.
    const placements = placeEdgeLabels(graph, curves), accepted = [];
    assert.deepEqual(placements, placeEdgeLabels(graph, curves));
    assert.ok(placements.size > 0);
    for (const edge of graph.edges) {
      const placement = placements.get(edge.id); if (!placement) continue;
      const box = {...placement.point, ...edgeLabelSize(edge)};
      for (const node of graph.nodes) assert.equal(boxIntersectionArea(box, {...node, ...graphNodeSize(node)}, 0), 0);
      for (const other of accepted) assert.equal(boxIntersectionArea(box, other, 0), 0);
      accepted.push(box);
    }
  }
});

test("node sizing responds to edited labels and node kinds", () => {
  const node = {label: "small", kind: "iri"};
  const before = graphNodeSize(node);
  node.label = "a considerably longer node title to test resizing";
  assert.ok(graphNodeSize(node).width > before.width);
  node.kind = "literal";
  assert.equal(graphNodeSize(node).height, 38);
});

test('bounded segment distance never discards a routing conflict', () => {
  let seed = 2026;
  const value = () => {seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 2 ** 32 * 2000 - 1000;};
  for (let i = 0; i < 5000; i++) {
    const points = Array.from({length: 4}, () => ({x: value(), y: value()}));
    const exact = segmentDistance(...points), bounded = segmentDistanceWithin(...points, 18);
    if (exact < 18) assert.equal(bounded, exact);
    else assert.ok(bounded === exact || bounded === Infinity);
  }
  assert.equal(segmentDistanceWithin({x: 0, y: 0}, {x: 10, y: 10}, {x: 400, y: 0}, {x: 400, y: 10}, 18), Infinity);
});
